import org.junit.runner.Description;
import org.junit.runner.JUnitCore;
import org.junit.runner.Request;
import org.junit.runner.Result;
import org.junit.runner.manipulation.Filter;
import org.junit.runner.notification.Failure;

public class RunFiltered {
    public static void main(String[] args) throws Exception {
        final String[] needles = args[0].split(",");
        Class<?>[] classes = new Class<?>[args.length - 1];
        for (int i = 1; i < args.length; i++) classes[i-1] = Class.forName(args[i]);
        Filter f = new Filter() {
            @Override public boolean shouldRun(Description d) {
                String m = d.getMethodName();
                if (m == null) return true;
                for (String n : needles) if (m.contains(n)) return true;
                return false;
            }
            @Override public String describe() { return "filtered"; }
        };
        int run = 0, fail = 0;
        for (Class<?> c : classes) {
            Result r = new JUnitCore().run(Request.aClass(c).filterWith(f));
            run += r.getRunCount();
            fail += r.getFailureCount();
            for (Failure x : r.getFailures()) System.out.println(x.toString());
        }
        System.out.println("RUN=" + run + " FAIL=" + fail);
        if (fail > 0) System.exit(1);
    }
}
